class iam_service_account_unused(Check):
    def execute(self) -> Check_Report_GCP:
        findings = []
        max_unused_days = monitoring_client.audit_config.get(
            "max_unused_account_days", 180
        )
        sa_ids_used = monitoring_client.sa_api_metrics
        for account in iam_client.service_accounts:
            report = Check_Report_GCP(
                metadata=self.metadata(),
                resource=account,
                resource_id=account.email,
                location=iam_client.region,
            )
            if account.disabled:
                report.status = "PASS"
                report.status_extended = (
                    f"Service Account {account.email} is disabled and cannot be used."
                )
            elif account.uniqueId in sa_ids_used:
                report.status = "PASS"
                report.status_extended = f"Service Account {account.email} was used over the last {max_unused_days} days."
            else:
                report.status = "FAIL"
                report.status_extended = f"Service Account {account.email} was not used over the last {max_unused_days} days."
            findings.append(report)

        return findings

query "iam_service_account_key_age_100" {
  sql = <<-EOQ
    select
      'https://iam.googleapis.com/v1/projects/' || project || '/serviceAccounts/' || service_account_name || '/keys/' || name as resource,
    case
      when valid_after_time <= (current_date - interval '100' day) then 'alarm'
      else 'ok'
    end as status,
    service_account_name || ' ' || name || ' created ' || to_char(valid_after_time , 'DD-Mon-YYYY') ||
      ' (' || extract(day from current_timestamp - valid_after_time) || ' days).'
    as reason
    ${local.common_dimensions_global_sql}
  from
    gcp_service_account_key;
  EOQ
}

